package com.trough.hot;
import android.view.*;import android.widget.*;import java.io.File;import org.json.*;
/** Explicit existing-panel layout action. Never launches an Activity or changes chat text. */
final class HalfSwordPresentation {
 static boolean layoutWindowReady(boolean attached,boolean shown,int visibility){return attached&&shown&&visibility==View.VISIBLE;}
 static boolean expandPreview(String mode){return "full".equals(mode)||"split".equals(mode);}
 private static String lastState="";private static long lastReport;
 private static void state(FrameLayout root,String why,HalfSwordView v){long now=System.currentTimeMillis();if(why.equals(lastState)&&now-lastReport<5000)return;lastState=why;lastReport=now;try{JSONObject o=new JSONObject().put("state",why).put("attached",root.isAttachedToWindow()).put("window_focus",root.hasWindowFocus()).put("time_ms",now);if(v!=null)o.put("view_attached",v.isAttachedToWindow()).put("running",v.characterRunning).put("busy",v.characterBusy).put("touch_owners",v.touchCapture.owners());Payloads.writeSmall(new File(root.getContext().getFilesDir(),"home/.trough/half-sword-view-runtime.json"),o.toString());}catch(Exception ignored){}}

 static void poll(final FrameLayout root,final android.app.Activity activity){final File request=new File(root.getContext().getFilesDir(),"home/.trough/half-sword-view-request");if(!request.isFile())return;if(lastState.length()==0)state(root,"consumer-reached",null);if(!layoutWindowReady(root.isAttachedToWindow(),root.isShown(),root.getWindowVisibility())){state(root,"window-deferred",null);return;}
  try{JSONObject r=new JSONObject(new String(Payloads.readSmall(request),"UTF-8"));final long id=r.getLong("requested_ms");final String mode=r.getString("mode");if(System.currentTimeMillis()-id>300000||!("full".equals(mode)||"split".equals(mode)||"preview".equals(mode))){request.delete();report(root,id,false,"Expired or invalid layout request",null);return;}
   View panel=null;for(int i=0;i<root.getChildCount();i++)if("half-sword-expanded".equals(root.getChildAt(i).getTag()))panel=root.getChildAt(i);if(panel==null&&expandPreview(mode)){View preview=root.findViewWithTag("half-sword-preview");HalfSwordView inline=preview==null?null:HalfSwordView.simulator(preview);if(inline==null||!inline.isAttachedToWindow()||inline.characterRunning||inline.characterBusy||inline.touchCapture.owners()!=0||activity==null){state(root,inline==null?"preview-absent":activity==null?"activity-absent":"preview-deferred",inline);return;}HalfSwordView.expand(activity,root,inline.viewport,inline);for(int i=0;i<root.getChildCount();i++)if("half-sword-expanded".equals(root.getChildAt(i).getTag()))panel=root.getChildAt(i);}if(panel==null){state(root,"panel-absent",null);return;}
   final HalfSwordView v=HalfSwordView.simulator(panel);if(v==null||!v.isAttachedToWindow()||v.characterRunning||v.characterBusy||v.touchCapture.owners()!=0){state(root,"panel-deferred",v);return;}
   if("preview".equals(mode)){Button back=HalfSwordViewCheck.button(panel,"Chat");if(back==null)throw new Exception("Missing existing preview control");if(!request.delete())return;if(!back.performClick())throw new Exception("Preview control rejected");report(root,id,true,"",null);return;}
   boolean want="full".equals(mode),current=Boolean.TRUE.equals(panel.getTag(0x7f0d74b4));Button button=HalfSwordViewCheck.button(panel,current?"Split view":"Full screen");if(button==null)throw new Exception("Missing existing layout control");if(!request.delete())return;state(root,"layout-applying",v);if(want!=current&&!button.performClick())throw new Exception("Layout control rejected");
   root.postDelayed(new Runnable(){public void run(){report(root,id,true,"",v);}},350);
  }catch(Exception error){request.delete();report(root,0,false,error.toString(),null);}
 }
 private static void report(FrameLayout root,long id,boolean applied,String error,HalfSwordView v){try{JSONObject o=new JSONObject().put("requested_ms",id).put("applied",applied).put("error",error).put("window_focus",root.hasWindowFocus()).put("time_ms",System.currentTimeMillis());if(v!=null)o.put("scene_visible",v.renderVisible).put("scene_width",v.getWidth()).put("scene_height",v.getHeight()).put("steps",v.characterSteps).put("running",v.characterRunning).put("fullscreen",Boolean.TRUE.equals(v.controlsRoot().getTag(0x7f0d74b4)));Payloads.writeSmall(new File(root.getContext().getFilesDir(),"home/.trough/half-sword-view-result.json"),o.toString());}catch(Exception ignored){}}
}
